#!/usr/bin/env python3
"""class-members-any-lookup-order.py <seed> [ts|js]: EVERY CLASS IS FRESH AND IS ASKED IN ANOTHER ORDER. Classes with methods, getters, setters, pairs, static ones, async | generator methods, methods called toString valueOf toJSON then constructor-like names, symbols, private ones, heirs one and two deep that override some. Steps, in a random order, each printing what it sees: read a method off an instance | off the prototype | off an heir's instance, call it, call it with another this, ask `in`, hasOwn, the descriptor, the names and keys of the prototype, for-in, typeof, name and length, read and store through an accessor, super calls, String(o) `${o}` o + "" JSON.stringify(o) await o (the engine's own looks by name), instanceof, the constructor, Object.getPrototypeOf chains, try to replace | delete | define a member. EVERY FUNCTION EVER SEEN IS KEPT, AND AT THE END THE TABLE OF WHICH IS THE SAME AS WHICH IS PRINTED: a member must be one function however and whenever it was first asked for. As plain or throws."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
TS = (sys.argv[2] if len(sys.argv) > 2 else 'js') == 'ts'
R = random.Random(seed)
A = ': any' if TS else ''
out = []; w = out.append
w('// generated by class-members-any-lookup-order.py %d' % seed)
if TS: w('declare const console: { log(...values: unknown[]): void };')
w('const lines%s = []; const sym = Symbol("s");' % (': string[]' if TS else ''))
w('const show = (v%s)%s => { try { return v === undefined ? "u" : typeof v === "function" ? "fn:" + v.name + "/" + v.length : typeof v === "symbol" ? String(v) : typeof v === "object" && v !== null ? JSON.stringify(v) : String(v); } catch (e) { return "?"; } };' % (A, ': string' if TS else ''))
w('const desc = (d%s) => d ? (("value" in d) ? "v" : (d.get ? "g" : "-") + (d.set ? "s" : "-")) + %s(d.enumerable ? "e" : "-") : "none";' % (A, '' if TS else '(d.writable ? "w" : "-") + (d.configurable ? "c" : "-") + '))
NAMES = ['m', 'n', 'run', 'toString', 'valueOf', 'toJSON', 'size', 'value', 'get', 'set', 'name', 'length', 'then2', 'x1']
def member(n, tag):
    k = R.random()
    if k < 0.45: return ('method', n, '%s(a%s, b%s) { return "%s.%s"; }' % (n, A, A, tag, n) if n not in ('toString', 'valueOf', 'toJSON') else '%s() { return "%s.%s"; }' % (n, tag, n))
    if k < 0.58: return ('getter', n, 'get %s() { return "%s.get %s"; }' % (n, tag, n))
    if k < 0.66: return ('pair', n, 'get %s() { return "%s.get %s"; } set %s(v%s) { seen.push("%s.set %s"); }' % (n, tag, n, n, A, tag, n))
    if k < 0.72: return ('setter', n, 'set %s(v%s) { seen.push("%s.set %s"); }' % (n, A, tag, n))
    if k < 0.80: return ('static', n, 'static %s() { return "%s.static %s"; }' % (n, tag, n)) if n not in ('name', 'length') else ('method', n, '%s() { return "%s.%s"; }' % (n, tag, n))
    if k < 0.86: return ('async', n, 'async %s() { return "%s.async %s"; }' % (n, tag, n))
    if k < 0.92: return ('generator', n, '*%s() { yield "%s.gen %s"; }' % (n, tag, n))
    return ('method', n, '%s() { return "%s.%s " + typeof this; }' % (n, tag, n))
w('const seen%s = [];' % (': string[]' if TS else ''))
for c in range(26):
    base = [member(n, 'B%d' % c) for n in R.sample(NAMES, R.randint(1, 6))]
    heir = [member(n, 'H%d' % c) for n in R.sample(NAMES, R.randint(0, 4))]
    if TS:
        kinds = {m[1]: m for m in base}
        heir = [h for h in heir if h[1] not in kinds] + [(k[0], k[1], k[2].replace('B%d.' % c, 'H%d.' % c)) for k in base if k[0] in ('method', 'getter', 'pair') and R.random() < 0.4 and k[1] not in ('toString', 'valueOf')]
    extra = R.random()
    w('{ class B { f = 1; %s %s %s }' % (' '.join(m[2] for m in base), '[sym]() { return "B.sym"; }' if extra < 0.3 else '', '#p() { return 1; } viaPrivate() { return this.#p(); }' if 0.3 < extra < 0.5 else ''))
    deep = R.random() < 0.7
    if deep: w('  class H extends B { g = 2; %s %s }' % (' '.join(m[2] for m in heir), 'viaSuper() { return super.%s; }' % base[0][1] if base[0][0] in ('method', 'getter', 'pair') else ''))
    C = 'H' if deep else 'B'
    w('  const kept%s = []; const keep = (label%s, v%s) => { if (typeof v === "function") kept.push([label, v]); return show(v); };' % (': [string, any][]' if TS else '', ': string' if TS else '', A))
    w('  const o%s = new %s(), o2%s = new %s(), P%s = %s.prototype, K%s = %s, BP%s = B.prototype;' % (A, C, A, C, A, C, A, C, A))
    w('  const step = (name%s, f%s) => { let s; try { s = f(); } catch (e) { s = "THROWS " + (e%s).name; } lines.push("%d " + name + ": " + s); };' % (': string' if TS else '', ': () => any' if TS else '', ' as Error' if TS else '', c))
    names = sorted(set(m[1] for m in base + heir)) + ['absent']
    steps = []
    for n in names:
        steps += [('read %s off an instance' % n, 'keep("o.%s", o.%s)' % (n, n)), ('read %s off another' % n, 'keep("o2.%s", o2.%s)' % (n, n)), ('read %s off the prototype' % n, 'keep("P.%s", P.%s)' % (n, n)), ('read %s off the base' % n, 'keep("BP.%s", BP.%s)' % (n, n)),
                  ('read %s off the class' % n, 'keep("K.%s", K.%s)' % (n, n)), ('call %s' % n, 'show(o.%s(1, 2))' % n), ('call %s with another this' % n, 'show(o.%s.call({ f: 9 }))' % n), ('%s in' % n, '["%s" in o, "%s" in P, "%s" in K].join()' % (n, n, n)),
                  ('hasOwn %s' % n, '[Object.hasOwn(o, "%s"), Object.hasOwn(P, "%s"), Object.hasOwn(BP, "%s"), Object.hasOwn(K, "%s")].join()' % (n, n, n, n)), ('descriptor of %s' % n, '(() => { const d = Object.getOwnPropertyDescriptor(P, "%s"), e = Object.getOwnPropertyDescriptor(BP, "%s"); if (d) { keep("dP.%s", d.value); keep("dP.get %s", d.get); keep("dP.set %s", d.set); } if (e) { keep("dBP.%s", e.value); keep("dBP.get %s", e.get); } return desc(d) + " " + desc(e); })()' % (n, n, n, n, n, n, n)),
                  ('store %s' % n, '(() => { o.%s = "stored"; return show(o.%s) + " " + Object.hasOwn(o, "%s") + " " + seen.splice(0).join(); })()' % (n, n, n)), ('by a key %s' % n, 'keep("o[%s]", o["%s".slice(0)])' % (n, n)), ('replace %s' % n, '(() => { P.%s = () => "replaced"; return show(o2.%s); })()' % (n, n)), ('delete %s' % n, 'String(delete P.%s) + " " + ("%s" in o2)' % (n, n)),
                  ('define %s' % n, '(() => { Object.defineProperty(P, "%s", { value: () => "defined", configurable: true, writable: true }); return show(o2.%s); })()' % (n, n)), ('bind %s' % n, 'show(o.%s.bind(o2)())' % n)]
    steps += [('names of the prototype', 'Object.getOwnPropertyNames(P).join()'), ('names of the base', 'Object.getOwnPropertyNames(BP).join()'), ('keys', 'Reflect.ownKeys(P).map(String).join()'), ('names of the class', 'Object.getOwnPropertyNames(K).join()'), ('for in', '(() => { const r = []; for (const k in o) r.push(k); return r.join(); })()'),
              ('String', 'String(o)'), ('template', '`${o}`'), ('plus', 'o + ""'), ('number', 'String(+o)'), ('stringify', 'JSON.stringify(o)'), ('stringify inside', 'JSON.stringify({ o })'), ('instanceof', '[o instanceof B, o instanceof K, P instanceof B, Object.create(P) instanceof K].join()'),
              ('constructor', '[o.constructor === K, P.constructor === K, BP.constructor === B, Object.hasOwn(P, "constructor")].join()'), ('chain', '[Object.getPrototypeOf(o) === P, Object.getPrototypeOf(P) === BP || P === BP, Object.getPrototypeOf(K) === B || K === B].join()'), ('all descriptors', 'Object.entries(Object.getOwnPropertyDescriptors(P)).map(([k, d]) => k + ":" + desc(d)).join()'),
              ('symbol', 'keep("o[sym]", o[sym])'), ('via private', 'show(o.viaPrivate && o.viaPrivate())'), ('via super', 'keep("super", o.viaSuper && o.viaSuper())'), ('frozen', '[Object.isFrozen(P), Object.isExtensible(P), Object.isSealed(P)].join()'), ('typeof', '[typeof P, typeof K, Object.prototype.toString.call(P)].join()'), ('an heir made late', '(() => { class L extends K {} const l%s = new L(); return keep("late.%s", l.%s); })()' % (A, names[0], names[0])),
              ('Object.create', 'keep("created.%s", Object.create(P).%s)' % (names[0], names[0])), ('assign', 'JSON.stringify(Object.assign({}, o))'), ('spread', 'JSON.stringify({ ...o })'), ('entries of the prototype', 'JSON.stringify(Object.entries(P))')]
    R.shuffle(steps)
    hard = [s for s in steps if s[0].startswith(('replace', 'delete', 'define'))]; soft = [s for s in steps if s not in hard and not (TS and s[0] == 'frozen')]
    if TS: hard = []
    chosen = soft[:R.randint(10, 22)] + (hard[:1] if R.random() < 0.3 else []) + soft[22:R.randint(22, 30)]
    for name, e in chosen: w('  step(%r, () => %s);' % (name, e))
    w('  lines.push("%d the same: " + kept.map(([l, f], i) => l + "=" + kept.findIndex(([, g]) => g === f)).join(" ")); }' % c)
w('for (const line of lines) console.log(line);')
print('\n'.join(out))
